package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.ethk3.novaonepro.*;
import java.io.*;
import java.util.*;
import java.util.function.Supplier;
/** Pretrained private snapshots. P0 only forecasts; feedback training stays in the fenced P2 queue. */
public final class LivePoolR26 {
    private LivePoolR26() {}
    private static final int LIMIT=32;
    private static final class Row {String policy,text,hash,checkpoint,family;byte[] state;long through,genesis,born;}
    private static Row row(Cursor c){Row r=new Row();r.policy=c.getString(0);r.text=c.getString(1);r.state=c.getBlob(2);r.hash=c.getString(3);r.checkpoint=c.getString(4);r.through=c.getLong(5);r.genesis=c.getLong(6);r.born=c.getLong(7);return r;}
    private static final String COLUMNS="policy_hash,canonical_text,state,state_hash,checkpoint_hash,through_ordinal,genesis_ordinal,born_ordinal";
    private static int changes(SQLiteDatabase db){try(Cursor c=db.rawQuery("SELECT changes()",null)){return c.moveToFirst()?c.getInt(0):0;}}
    /** One complete state is verified off-writer and atomically installed. Existing family parents stay active. */
    public static long publishOne(DbStore store,Supplier<RuntimeCoordinatorR26.Claim> claims,BudgetTokenSU1 budget)throws IOException{
        long legacyPublished=LegacyPublicationR26.publishOne(store,claims,budget);if(legacyPublished>0)return legacyPublished;
        Set<String> activeFamilies=new HashSet<>();try(Cursor c=store.readable().rawQuery("SELECT family_id FROM r26_live_model WHERE status='ACTIVE'",null)){while(c.moveToNext())activeFamilies.add(c.getString(0));}
        if(activeFamilies.stream().filter(f->!f.startsWith("L:")).count()>=24)return 0;
        Row prepared=null;String campaign=null;long through=0;String abi=ResearchSemanticsGeneratedR967.TRAINING_RULE_SHA256;
        try(Cursor c=store.readable().rawQuery("SELECT a.policy_hash,a.canonical_text,a.state,a.state_hash,a.checkpoint_hash,f.source_through,f.campaign_id,f.snapshot FROM r26_candidate a JOIN r26_foundry f ON f.campaign_id=a.campaign_id WHERE a.status='DONE' AND f.status='DONE' AND f.numerical_abi=? AND a.canonical_text LIKE '%R26F%' AND NOT EXISTS(SELECT 1 FROM r26_live_model l WHERE l.policy_hash=a.policy_hash) ORDER BY f.created_at DESC,CASE WHEN a.val_n>0 THEN 1.0*a.val_k/a.val_n ELSE -1 END DESC,a.policy_hash",new String[]{abi})){while(c.moveToNext()){
            budget.checkpointOrYield();ModelGenomeSU2 g=ModelGenomeSU2.parse(c.getString(1));if(g.members.size()!=1||!g.members.get(0).kind.startsWith("R26F")||!g.sink||!g.key().equals(c.getString(0)))continue;String family=g.members.get(0).kind.substring(3);if(activeFamilies.contains(family))continue;
            LiveStateR26 state=LiveStateR26.decode(c.getString(1),CheckpointArtifactsR26.resolve(store,c.getBlob(2)),c.getString(3));if(state.samples()<128)continue;FoundryCampaignR26.Snapshot source=FoundryCampaignR26.Snapshot.decode(c.getBlob(7));
            Row r=new Row();r.policy=g.key();r.text=g.text();r.state=c.getBlob(2);r.hash=c.getString(3);r.checkpoint=c.getString(4);r.through=c.getLong(5);r.genesis=source.ordinal[0];r.born=r.through+1;r.family=family;prepared=r;through=r.through;campaign=c.getString(6);break;
        }}
        if(prepared==null)return 0;budget.checkpointOrYield();final Row r=prepared;final String birthCampaign=campaign;final long sourceThrough=through;
        return store.coordinatorForResearchR952().runAtomicWriteOrThrowF01("R26_LIVE_PUBLICATION",db->{RuntimeCoordinatorR26.requireFence(db,claims.get());long now=System.currentTimeMillis();
            // Freeze birth against the writer's current raw and terminal cursors, never the historical bootstrap.
            try(Cursor latest=db.rawQuery("SELECT issue FROM draws WHERE dirty=0 ORDER BY issue DESC LIMIT 1",null)){if(latest.moveToFirst())r.born=Math.max(r.born,TargetIssueResolver.sequenceOrdinalSU1(latest.getString(0))+1);}
            try(Cursor latest=db.rawQuery("SELECT max(issue_ordinal) FROM r26_feedback",null)){if(latest.moveToFirst()&&!latest.isNull(0))r.born=Math.max(r.born,latest.getLong(0)+1);}
            try(Cursor capacity=db.rawQuery("SELECT count(*) FROM r26_live_model WHERE status='ACTIVE'",null)){capacity.moveToFirst();if(capacity.getInt(0)>=LIMIT)return 0L;}
            try(Cursor c=db.rawQuery("SELECT 1 FROM r26_live_model WHERE family_id=? AND status='ACTIVE'",new String[]{r.family})){if(c.moveToFirst())return 0L;}
            try(Cursor c=db.rawQuery("SELECT 1 FROM r26_candidate WHERE campaign_id=? AND policy_hash=? AND state_hash=? AND checkpoint_hash=? AND status='DONE'",new String[]{birthCampaign,r.policy,r.hash,r.checkpoint})){if(!c.moveToFirst())throw new IllegalStateException("R26_PUBLICATION_CAS");}
            db.execSQL("INSERT INTO r26_live_model(policy_hash,canonical_text,state,state_hash,checkpoint_hash,parent_hash,through_ordinal,genesis_ordinal,born_ordinal,updated_at,family_id) VALUES(?,?,?,?,?,'',?,?,?,?,?)",new Object[]{r.policy,r.text,r.state,r.hash,r.checkpoint,r.through,r.genesis,r.born,now,r.family});
            ModelGenomeSU2 g=ModelGenomeSU2.parse(r.text);ModelEvolutionSU2.Ranked ranked=new ModelEvolutionSU2.Ranked(g,"R26_LIVE","","SHADOW ONLY UNTIL NEW FUTURE QUALIFICATION");ModelStoreSU2.saveGenome(db,ranked,birthCampaign,sourceThrough,0,0,"RESEARCH",now);db.execSQL("UPDATE su2_model_genome SET origin_op='R26_LIVE' WHERE genome_key=?",new Object[]{r.policy});ModelStoreSU2.joinLeague(db,"SU2:"+r.policy,"SU2",r.family+"·R26未来影子·待资格",r.policy,r.born);CertificateSU2.preregister(db,r.policy,r.born);return 1L;});
    }
    public static long trainOne(DbStore store,Supplier<RuntimeCoordinatorR26.Claim> claims,BudgetTokenSU1 budget)throws IOException{
        Models.Draw latest=store.getLatestDraw();if(latest==null)return 0;long latestOrdinal=TargetIssueResolver.sequenceOrdinalSU1(latest.issue);
        Row r=null;try(Cursor c=store.readable().rawQuery("SELECT "+COLUMNS+" FROM r26_live_model WHERE status='ACTIVE' AND through_ordinal<? ORDER BY updated_at,policy_hash LIMIT 1",new String[]{String.valueOf(latestOrdinal)})){if(c.moveToFirst())r=row(c);}if(r==null)return 0;
        final Row failed=r;
        try{return trainRow(store,claims,budget,r);}catch(BudgetTokenSU1.Yield yielded){throw yielded;}catch(IOException|IllegalArgumentException failure){
            if(String.valueOf(failure.getMessage()).contains("CAPACITY_WAIT_FOR_RETENTION")){claims.get().reason("CHECKPOINT_CAPACITY_WAIT_FOR_RETENTION");return 0;}
            store.coordinatorForResearchR952().runAtomicWriteOrThrowF01("R26_LIVE_QUARANTINE",db->{RuntimeCoordinatorR26.requireFence(db,claims.get());db.execSQL("UPDATE r26_live_model SET status='BLOCKED_INPUT_OR_STATE' WHERE policy_hash=? AND checkpoint_hash=?",new Object[]{failed.policy,failed.checkpoint});db.execSQL("INSERT OR REPLACE INTO r26_live_failure VALUES(?,?,?,?)",new Object[]{failed.policy,failed.through+1,failure.toString(),System.currentTimeMillis()});return 0;});return 0;
        }
    }
    private static long trainRow(DbStore store,Supplier<RuntimeCoordinatorR26.Claim> claims,BudgetTokenSU1 budget,Row r)throws IOException{
        final Row previous=r;if(!CurrentPolicyR26.matches(r.text,r.policy)){store.coordinatorForResearchR952().runAtomicWriteOrThrowF01("R26_LIVE_ABI_BLOCK",db->{RuntimeCoordinatorR26.requireFence(db,claims.get());db.execSQL("UPDATE r26_live_model SET status='NUMERICAL_ABI_CHANGED' WHERE policy_hash=?",new Object[]{previous.policy});return 0;});return 0;}
        String[] input=LegacyReplayR26.nextInput(store,r.through);if(input==null)return 0;
        final long ordinal=Long.parseLong(input[3]);final boolean gap=ordinal>r.through+1;String event=input[0],source=input[2];
        Models.Draw actual=store.getDrawByIssue(input[1]);if(actual==null||!source.equals(DrawHashR36.sha256V2(actual)))throw new IOException("R26_LIVE_SOURCE_MISSING_OR_REVISED");int[] draw=actual.numbers.clone();
        PolicyRuntimeR26 learner=PolicyCheckpointR26.restore(CheckpointArtifactsR26.forStore(store),r.text,r.state,r.hash);budget.checkpointOrYield();if(gap)learner.onGap();
        List<Models.Draw> history=store.getDrawsBeforeIssue(actual.issue,480);long[] issues=new long[history.size()+1],open=new long[issues.length],available=new long[issues.length];int[][] d=new int[issues.length][10];for(int i=0;i<history.size();i++){Models.Draw h=history.get(i);issues[i]=Long.parseLong(h.issue);open[i]=h.openTime;available[i]=h.fetchTime;d[i]=h.numbers.clone();}issues[history.size()]=Long.parseLong(actual.issue);open[history.size()]=actual.openTime;available[history.size()]=actual.fetchTime;d[history.size()]=draw;
        LegacyTeacherOwnerR26.enter(issues,open,available,d,history.size());try{ModelLiveSU2.Decision replayed=learner.forecast();
            try(Cursor c=store.readable().rawQuery("SELECT position,number_mask,act,phat FROM su2_live_decision WHERE genome_key=? AND sequence_ordinal=?",new String[]{r.policy,String.valueOf(ordinal)})){if(c.moveToFirst()&&(c.getInt(0)!=replayed.position||c.getInt(1)!=replayed.mask||c.getInt(2)!=(replayed.act?1:0)||(!c.isNull(3)&&Math.abs(c.getDouble(3)-replayed.phat)>1e-8)))throw new IOException("R26_FROZEN_REPLAY_MISMATCH");}
            learner.learn(draw,ordinal);
        }finally{LegacyTeacherOwnerR26.leave();}
        final String eventId=event,sourceHash=source;
        try(CheckpointArtifactsR26.Prepared file=PolicyCheckpointR26.prepare(CheckpointArtifactsR26.forStore(store),learner)){final String stateHash=LiveStateR26.hash(CheckpointArtifactsR26.forStore(store).resolve(file.reference())),checkpoint=HashingSU1.fields("R26_LIVE_CHECKPOINT_V1",r.policy,r.checkpoint,event,stateHash);store.coordinatorForResearchR952().runAtomicWriteOrThrowF01("R26_LIVE_LEARN_COMMIT",db->{RuntimeCoordinatorR26.requireFence(db,claims.get());
            db.execSQL("UPDATE r26_live_model SET state=?,state_hash=?,checkpoint_hash=?,parent_hash=?,through_ordinal=?,updated_at=? WHERE policy_hash=? AND checkpoint_hash=? AND through_ordinal=? AND status='ACTIVE'",new Object[]{file.reference(),stateHash,checkpoint,previous.checkpoint,ordinal,System.currentTimeMillis(),previous.policy,previous.checkpoint,previous.through});if(changes(db)!=1)throw new IllegalStateException("R26_LIVE_PARENT_CAS");
            if(!eventId.isEmpty())try(Cursor c=db.rawQuery("SELECT 1 FROM r26_feedback WHERE event_id=? AND source_hash=?",new String[]{eventId,sourceHash})){if(!c.moveToFirst())throw new IllegalStateException("R26_LIVE_EVENT_CAS");}
            CheckpointManifestR26.record(db,checkpoint,previous.policy,sourceHash,previous.checkpoint,ordinal,file.reference());
            db.execSQL("UPDATE r26_capability SET state='LIVE_TRAINING_PROGRESS',last_progress=?,reason='Canonical revealed label and full live checkpoint committed' WHERE kind='FAMILY' AND mechanism=(SELECT family_id FROM r26_live_model WHERE policy_hash=?)",new Object[]{System.currentTimeMillis(),previous.policy});
            if(!eventId.isEmpty())db.execSQL("INSERT INTO r26_consumption VALUES(?,?,?,'REVEALED_LIVE_LABEL')",new Object[]{eventId,previous.policy,checkpoint});
            if(gap){db.execSQL("INSERT OR IGNORE INTO r26_gap_receipt VALUES(?,?,?,?,?,?)",new Object[]{previous.policy,previous.through,ordinal,ordinal-previous.through-1,"UNKNOWN_LABELS; PARAMETERS_RETAINED; TEMPORAL_CONTEXT_REBUILT",System.currentTimeMillis()});db.execSQL("INSERT OR IGNORE INTO r26_certificate_revocation SELECT certificate_id,'DATA_GAP_REQUIRES_NEW_QUALIFICATION',? FROM su2_certificate WHERE genome_key=?",new Object[]{System.currentTimeMillis(),previous.policy});}
            return 0;});}return 1;
    }
    public static int capture(DbStore store,String target){if(!RuntimeSchemaR26.ready(store.readable()))return 0;long seq=TargetIssueResolver.sequenceOrdinalSU1(target);EventFrameSU1 frame=EventFrameBuilderSU1.captureWithGapsR26(store,target);List<Row> rows=new ArrayList<>();try(Cursor c=store.readable().rawQuery("SELECT "+COLUMNS+" FROM r26_live_model WHERE status='ACTIVE' AND through_ordinal=? AND born_ordinal<=? ORDER BY policy_hash LIMIT ?",new String[]{String.valueOf(seq-1),String.valueOf(seq),String.valueOf(LIMIT)})){while(c.moveToNext())rows.add(row(c));}
        Collections.rotate(rows,rows.isEmpty()?0:(int)(seq%rows.size()));Map<Row,ModelLiveSU2.Decision> decisions=new LinkedHashMap<>();Map<String,byte[]> tables=new HashMap<>();long stop=System.nanoTime()+1_000_000_000L;
        BudgetTokenSU1 forecastBudget=new BudgetTokenSU1(1000,3000000,()->SettlementExecutionGateR819.isActive());
        ExecutionBudgetR26.enter(forecastBudget);try{for(Row r:rows){if(System.nanoTime()>stop||SettlementExecutionGateR819.isActive())break;try{if(!CurrentPolicyR26.matches(r.text,r.policy))continue;PolicyRuntimeR26 state=PolicyCheckpointR26.restore(CheckpointArtifactsR26.forStore(store),r.text,r.state,r.hash);ModelLiveSU2.Decision decision=state.forecast();tables.put(r.policy,encodeTable(state.table()));decisions.put(r,decision);}catch(BudgetTokenSU1.Yield yield){break;}catch(IOException|IllegalArgumentException bad){android.util.Log.w("STARCORE_R26","live forecast blocked",bad);}}}finally{ExecutionBudgetR26.leave();}
        if(decisions.isEmpty())return 0;return store.coordinatorForResearchR952().runAtomicWriteOrThrowF01("R26_LIVE_FREEZE",db->{if(!EventFrameBuilderSU1.unchanged(store,frame))return 0;long now=System.currentTimeMillis();if(now>=frame.targetOpenTime)return 0;int count=0;for(Map.Entry<Row,ModelLiveSU2.Decision> e:decisions.entrySet()){Row r=e.getKey();try(Cursor c=db.rawQuery("SELECT 1 FROM r26_live_model WHERE policy_hash=? AND checkpoint_hash=? AND through_ordinal=? AND status='ACTIVE'",new String[]{r.policy,r.checkpoint,String.valueOf(seq-1)})){if(!c.moveToFirst())continue;}
            db.execSQL("INSERT OR IGNORE INTO r26_frozen VALUES(?,?,?,?,?,?,?,?,?,?)",new Object[]{r.policy,seq,seq-1,r.checkpoint,r.hash,frame.sourceVersionHash,frame.sourceGeneration,now,frame.targetOpenTime,tables.get(r.policy)});ModelStoreSU2.insertDecision(db,r.policy,seq,e.getValue(),now,frame.targetOpenTime);count++;}return count;});
    }
    private static byte[] encodeTable(float[][] table)throws IOException{if(table==null||table.length!=10)throw new IOException("R26_TABLE_SHAPE");ByteArrayOutputStream b=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(b)){for(int p=0;p<10;p++){double row=0,col=0;for(int n=0;n<10;n++){float q=table[p][n];if(!Float.isFinite(q)||q<0||q>1)throw new IOException("R26_TABLE_RANGE");row+=q;col+=table[n][p];out.writeFloat(q);}if(Math.abs(row-1)>1e-4||Math.abs(col-1)>1e-4)throw new IOException("R26_TABLE_INCOHERENT");}}return b.toByteArray();}
    public static float[][] frozenTable(SQLiteDatabase db,String policy,long seq){if(!RuntimeSchemaR26.ready(db))return null;try(Cursor c=db.rawQuery("SELECT probability_table FROM r26_frozen WHERE policy_hash=? AND target_ordinal=? AND input_through<? AND frozen_at<deadline_at",new String[]{policy,String.valueOf(seq),String.valueOf(seq)})){if(!c.moveToFirst())return null;try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(c.getBlob(0)))){float[][] p=new float[10][10];for(int i=0;i<10;i++)for(int j=0;j<10;j++)p[i][j]=in.readFloat();encodeTable(p);return p;}}catch(IOException bad){throw new IllegalStateException("R26_FROZEN_TABLE_CORRUPT",bad);}}
}
